//! Tokenization and argument extraction used by the command-pattern macro.
//!
//! Code generated by `#[processor(command = "...")]` splits message text on ASCII
//! whitespace into tokens and uses [`CommandLopper`] to match literal text, numbers, enum
//! options, and text arguments in pattern order. The type is also public for hand-written
//! command parsers, but it does not automatically handle non-text segments in a message
//! chain.

use regex::Regex;

/// Consumes tokens from tokenized command text in order.
///
/// Construct it with a token list that the caller has already trimmed and split with
/// `split_ascii_whitespace`. All extraction methods share one cursor: a successful
/// consumption advances the cursor, while a failure usually leaves it in place. Matching a
/// command typically requires calling several methods in pattern order.
pub struct CommandLopper<'a> {
    current_slice: &'a str,
    next_idx: usize,
    tokens: Vec<&'a str>,
}

impl<'a> CommandLopper<'a> {
    /// Creates a cursor over the given token list, initially positioned at the first token.
    ///
    /// An empty list means there is nothing to match; methods return `None` or `false` and
    /// do not panic.
    pub fn new(tokens: Vec<&'a str>) -> Self {
        Self {
            current_slice: "",
            next_idx: 0,
            tokens,
        }
    }
}

impl CommandLopper<'_> {
    fn check_next_slice(&mut self) {
        if self.current_slice.is_empty() {
            if self.next_idx < self.tokens.len() {
                self.current_slice = self.tokens[self.next_idx];
                self.next_idx += 1;
            }
        }
    }

    /// Tries to match the start of the current token against one of the `enums` prefixes.
    ///
    /// Prefixes are tried in `enums` order. On a match, the matched prefix is returned and
    /// removed from the current token; the remainder stays available for later methods.
    /// Returns `None` when the current token is empty or no prefix matches, leaving the
    /// cursor unchanged. This is a prefix match, so `"runbot"` can match `"run"`; use
    /// [`Self::cut_plain_text`] when a complete token must match.
    pub fn next_enum(&mut self, enums: &[&str]) -> Option<String> {
        self.check_next_slice();
        if self.current_slice.is_empty() {
            return None;
        }
        for enum_str in enums {
            if self.current_slice.starts_with(enum_str) {
                self.current_slice = self.current_slice.strip_prefix(enum_str).unwrap_or("");
                return Some(enum_str.to_string());
            }
        }
        None
    }

    /// Tries to consume a literal token equal to the current token.
    ///
    /// Returns `true` and marks the token consumed only when the current token is exactly
    /// equal to `text`; it performs no prefix or substring match and does not ignore case.
    /// Returns `false` when the current token is empty or different, leaving the cursor
    /// unchanged. After consumption, the next call advances to the following token.
    pub fn cut_plain_text(&mut self, text: &str) -> bool {
        self.check_next_slice();
        if self.current_slice.is_empty() {
            return false;
        }
        if self.current_slice == text {
            self.current_slice = "";
            return true;
        }
        false
    }

    /// Extracts an integer or decimal number from the start of the current token.
    ///
    /// The pattern is `^\d+([.]\d+)?`. The return value keeps the original text form
    /// (for example `"123.45"`) and the extracted part is removed from the current token.
    /// Returns `None` when the current token does not start with a digit, leaving the
    /// cursor unchanged. This method does not parse the number and does not handle signs,
    /// scientific notation, or leading whitespace.
    pub fn next_number(&mut self) -> Option<String> {
        self.check_next_slice();
        if self.current_slice.is_empty() {
            return None;
        }
        let re = Regex::new(r"^\d+([.]\d+)?").unwrap();
        let caps = re.captures(self.current_slice);
        if caps.is_none() {
            return None;
        }
        let caps = caps.unwrap();
        let num = caps.get(0).unwrap().as_str().to_string();
        self.current_slice = self.current_slice.strip_prefix(num.as_str()).unwrap_or("");
        Some(num)
    }

    /// Takes all remaining text of the current token as a "text until whitespace" argument.
    ///
    /// Because the input was already split on ASCII whitespace, this returns the remainder
    /// of the current token only and does not append later tokens. After returning `Some`,
    /// the current token is consumed and the next call advances to the following token;
    /// returns `None` when the current token is empty.
    pub fn cut_text_to_space(&mut self) -> Option<String> {
        self.check_next_slice();
        if self.current_slice.is_empty() {
            return None;
        }
        let result = self.current_slice.to_string();
        self.current_slice = "";
        Some(result)
    }

    /// Takes the current token and all following tokens and joins them with single spaces.
    ///
    /// All remaining tokens are consumed, which suits a trailing `{name:e}` argument in a
    /// command pattern. Returns `None` when no tokens remain. Whitespace in the result is
    /// normalized by tokenization, so original runs of spaces are not preserved.
    pub fn cut_text_to_end(&mut self) -> Option<String> {
        self.check_next_slice();
        if self.current_slice.is_empty() {
            return None;
        }
        let mut buffer = self.current_slice.to_string();
        self.current_slice = "";
        loop {
            self.check_next_slice();
            if self.current_slice.is_empty() {
                break;
            }
            buffer += " ";
            buffer += self.current_slice;
            self.current_slice = "";
        }
        Some(buffer)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cut_plain_text_exact_match() {
        // Exact match: "runbot" must not match "run".
        let mut lopper = CommandLopper::new(vec!["runbot"]);
        assert!(!lopper.cut_plain_text("run"), "runbot should not match run");
        
        // Exact match: "runbot" must match "runbot".
        let mut lopper = CommandLopper::new(vec!["runbot"]);
        assert!(lopper.cut_plain_text("runbot"), "runbot should match runbot");
    }

    #[test]
    fn test_cut_plain_text_multi_token() {
        // Multiple tokens: "run bot" must not match "run" because tokens remain.
        let mut lopper = CommandLopper::new(vec!["run", "bot"]);
        assert!(lopper.cut_plain_text("run"), "first token should match");
        // Check whether tokens remain.
        assert!(!lopper.current_slice.is_empty() || lopper.next_idx < lopper.tokens.len(), 
                "should have remaining tokens");
        
        // Multiple tokens: "run bot" must match "run bot" completely.
        let mut lopper = CommandLopper::new(vec!["run", "bot"]);
        assert!(lopper.cut_plain_text("run"));
        lopper.check_next_slice();
        assert!(lopper.cut_plain_text("bot"));
    }

    #[test]
    fn test_cut_plain_text_single_token() {
        // Single token: "run" must match "run".
        let mut lopper = CommandLopper::new(vec!["run"]);
        assert!(lopper.cut_plain_text("run"), "run should match run");
        assert!(lopper.current_slice.is_empty(), "should consume the token");
    }

    #[test]
    fn test_cut_plain_text_no_match() {
        // Non-matching case.
        let mut lopper = CommandLopper::new(vec!["hello"]);
        assert!(!lopper.cut_plain_text("world"), "hello should not match world");
    }

    #[test]
    fn test_cut_plain_text_empty() {
        // Empty input.
        let mut lopper = CommandLopper::new(vec![]);
        assert!(!lopper.cut_plain_text("run"), "empty should not match");
    }

    #[test]
    fn test_next_enum_prefix_match() {
        // Prefix match (for prefixes such as -, /, ~).
        let mut lopper = CommandLopper::new(vec!["-runbot"]);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        assert_eq!(lopper.current_slice, "runbot");
        
        // Multiple prefix options.
        let mut lopper = CommandLopper::new(vec!["/test"]);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("/".to_string()));
    }

    #[test]
    fn test_next_enum_no_match() {
        // Enum does not match.
        let mut lopper = CommandLopper::new(vec!["runbot"]);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), None);
    }

    #[test]
    fn test_next_number() {
        // Number match.
        let mut lopper = CommandLopper::new(vec!["123"]);
        assert_eq!(lopper.next_number(), Some("123".to_string()));
        
        // Decimal number.
        let mut lopper = CommandLopper::new(vec!["123.45"]);
        assert_eq!(lopper.next_number(), Some("123.45".to_string()));
        
        // Non-number.
        let mut lopper = CommandLopper::new(vec!["abc"]);
        assert_eq!(lopper.next_number(), None);
    }

    #[test]
    fn test_cut_text_to_space() {
        // Take text up to the next space.
        let mut lopper = CommandLopper::new(vec!["hello", "world"]);
        assert_eq!(lopper.cut_text_to_space(), Some("hello".to_string()));
        assert_eq!(lopper.cut_text_to_space(), Some("world".to_string()));
    }

    #[test]
    fn test_cut_text_to_end() {
        // Take text to the end.
        let mut lopper = CommandLopper::new(vec!["hello", "world", "test"]);
        assert_eq!(lopper.cut_text_to_end(), Some("hello world test".to_string()));
    }

    #[test]
    fn test_complex_scenario_run_vs_runbot() {
        // Full scenario: "runbot" must not match "run".
        let mut lopper = CommandLopper::new(vec!["-", "runbot"]);
        
        // Match the prefix.
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        
        // Matching "run" should fail.
        assert!(!lopper.cut_plain_text("run"), "runbot should not match run");
        
        // Reset and match "runbot"; this should succeed.
        let mut lopper = CommandLopper::new(vec!["-", "runbot"]);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        assert!(lopper.cut_plain_text("runbot"), "runbot should match runbot");
    }

    #[test]
    fn test_complex_scenario_run_bot() {
        // Full scenario: "run bot" must not match "run" alone.
        let mut lopper = CommandLopper::new(vec!["-", "run", "bot"]);
        
        // Match the prefix.
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        
        // Match "run".
        assert!(lopper.cut_plain_text("run"));
        
        // Check whether "bot" remains.
        lopper.check_next_slice();
        assert!(!lopper.current_slice.is_empty(), "should have remaining token 'bot'");
        
        // Match "run bot" completely.
        let mut lopper = CommandLopper::new(vec!["-", "run", "bot"]);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        assert!(lopper.cut_plain_text("run"));
        lopper.check_next_slice();
        assert!(lopper.cut_plain_text("bot"));
    }

    #[test]
    fn test_whitespace_handling() {
        // Exercise split_ascii_whitespace as in real usage.
        // Input "run bot  " should become ["run", "bot"].
        
        // Simulate trim() and split_ascii_whitespace().
        let input = "run bot  ";
        let tokens: Vec<&str> = input.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens, vec!["run", "bot"], "trailing spaces should be ignored");
        
        // Matching: "run bot" should match "run bot".
        let mut lopper = CommandLopper::new(tokens);
        assert!(lopper.cut_plain_text("run"), "should match 'run'");
        lopper.check_next_slice();
        assert!(lopper.cut_plain_text("bot"), "should match 'bot'");
    }

    #[test]
    fn test_whitespace_variations() {
        // Various whitespace variants.
        
        // 1. Multiple trailing spaces.
        let input1 = "run bot   ";
        let tokens1: Vec<&str> = input1.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens1, vec!["run", "bot"]);
        let mut lopper1 = CommandLopper::new(tokens1);
        assert!(lopper1.cut_plain_text("run"));
        lopper1.check_next_slice();
        assert!(lopper1.cut_plain_text("bot"));
        
        // 2. Leading spaces.
        let input2 = "  run bot";
        let tokens2: Vec<&str> = input2.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens2, vec!["run", "bot"]);
        let mut lopper2 = CommandLopper::new(tokens2);
        assert!(lopper2.cut_plain_text("run"));
        lopper2.check_next_slice();
        assert!(lopper2.cut_plain_text("bot"));
        
        // 3. Multiple spaces in the middle.
        let input3 = "run    bot";
        let tokens3: Vec<&str> = input3.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens3, vec!["run", "bot"]);
        let mut lopper3 = CommandLopper::new(tokens3);
        assert!(lopper3.cut_plain_text("run"));
        lopper3.check_next_slice();
        assert!(lopper3.cut_plain_text("bot"));
        
        // 4. Spaces on both ends.
        let input4 = "  run bot  ";
        let tokens4: Vec<&str> = input4.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens4, vec!["run", "bot"]);
        let mut lopper4 = CommandLopper::new(tokens4);
        assert!(lopper4.cut_plain_text("run"));
        lopper4.check_next_slice();
        assert!(lopper4.cut_plain_text("bot"));
    }

    #[test]
    fn test_whitespace_with_prefix() {
        // Case with a prefix: "-run bot  "
        let input = "-run bot  ";
        let tokens: Vec<&str> = input.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens, vec!["-run", "bot"]);
        
        // Note: "-run" is a single token here, so the prefix must be handled first.
        // In practice the prefix and command are separate: ["-", "run", "bot"].
        // This case is kept to exercise split_ascii_whitespace behavior.
        let input2 = "- run bot  ";
        let tokens2: Vec<&str> = input2.trim().split_ascii_whitespace().collect();
        assert_eq!(tokens2, vec!["-", "run", "bot"]);
        
        let mut lopper = CommandLopper::new(tokens2);
        assert_eq!(lopper.next_enum(&["-", "/", "~"]), Some("-".to_string()));
        assert!(lopper.cut_plain_text("run"));
        lopper.check_next_slice();
        assert!(lopper.cut_plain_text("bot"));
    }
}
